/* Orbit — browser-only utility workspace */
const $ = (id) => document.getElementById(id);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const store = {
  get(key, fallback) { try { const value = JSON.parse(localStorage.getItem('orbit_' + key)); return value ?? fallback; } catch { return fallback; } },
  set(key, value) { try { localStorage.setItem('orbit_' + key, JSON.stringify(value)); } catch { toast('Browser storage is full or unavailable.'); } }
};
let toastTimer;
function toast(message) { const el = $('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => el.classList.remove('show'), 2600); }
function escapeHTML(value='') { return String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function fmtBytes(bytes) { if (!bytes) return '0 B'; const units=['B','KB','MB','GB']; const i=Math.min(Math.floor(Math.log(bytes)/Math.log(1024)),3); return `${(bytes/1024**i).toFixed(i?1:0)} ${units[i]}`; }
function dateKey(date) { return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`; }
function dateLabel(key) { return new Date(`${key}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'}); }
function saveBlob(blob, name) { const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1500); }

// Navigation and home search
const viewNames = {home:'Home',calculator:'Calculator',converter:'Unit & currency converter',notes:'Notes',tasks:'To-do list',time:'Time tools',calendar:'Calendar & reminders',devices:'Device tools',files:'Files & PDF',media:'Media studio',games:'Games & quiz',habits:'Habit tracker',expenses:'Expense tracker',weather:'Weather',fitness:'Fitness tracker',meditation:'Meditation & sleep sounds'};
function showView(name) { if (!viewNames[name]) return; $$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`)); $$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.viewLink===name)); $('pageCrumb').textContent=viewNames[name]; $('sidebar').classList.remove('open'); window.scrollTo({top:0,behavior:'smooth'}); }
document.addEventListener('click', e=>{ const link=e.target.closest('[data-view-link]'); if(link){e.preventDefault();showView(link.dataset.viewLink);} });
$('menuToggle').addEventListener('click',()=>$('sidebar').classList.toggle('open'));
$('globalSearch').addEventListener('input', e=>{ const q=e.target.value.trim().toLowerCase(); if(!q)return; const found=Object.entries(viewNames).find(([key,label])=>key!=='home'&&(label.toLowerCase().includes(q)||key.includes(q))); if(found && (e.key==='Enter')) showView(found[0]); });
$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.target.value.toLowerCase();const found=Object.entries(viewNames).find(([k,v])=>k!=='home'&&(v.toLowerCase().includes(q)||k.includes(q)));if(found)showView(found[0]);else toast('No matching tool found.');}});
$('todayChip').textContent = new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'});
$('footerYear').textContent = new Date().getFullYear();

// Calculator
let calcExpr='';
function updateCalc(){ $('calcExpression').textContent=calcExpr||'Ready'; $('calcResult').textContent=calcExpr||'0'; }
function calculate(){ if(!calcExpr)return; if(!/^[0-9+*/().%\s-]+$/.test(calcExpr)){toast('That expression is not valid.');return;} try{const result=Function(`"use strict";return (${calcExpr})`)();if(!Number.isFinite(result))throw Error();$('calcExpression').textContent=calcExpr+' =';$('calcResult').textContent=Number(result.toPrecision(12)).toString();calcExpr=String(Number(result.toPrecision(12)));}catch{$('calcResult').textContent='Error';} }
$$('[data-calc]').forEach(b=>b.addEventListener('click',()=>{const v=b.dataset.calc;if(v==='clear')calcExpr='';else if(v==='back')calcExpr=calcExpr.slice(0,-1);else if(v==='equals'){calculate();return;}else if(v==='sign'){if(calcExpr.startsWith('-'))calcExpr=calcExpr.slice(1);else calcExpr='-'+calcExpr;}else calcExpr+=v;updateCalc();}));
document.addEventListener('keydown',e=>{if($('view-calculator').classList.contains('active')){if(/[0-9.+*/%()-]/.test(e.key)&&e.key.length===1){calcExpr+=e.key;updateCalc();}else if(e.key==='Backspace'){calcExpr=calcExpr.slice(0,-1);updateCalc();}else if(e.key==='Enter'){calculate();}else if(e.key==='Escape'){calcExpr='';updateCalc();}}});

// Unit conversion
const unitSets={
 length:{units:['Meter','Kilometer','Centimeter','Millimeter','Mile','Yard','Foot','Inch'],base:[1,1000,.01,.001,1609.344,.9144,.3048,.0254]},
 weight:{units:['Kilogram','Gram','Milligram','Pound','Ounce','Metric tonne'],base:[1,.001,.000001,.45359237,.028349523125,1000]},
 temperature:{units:['Celsius','Fahrenheit','Kelvin']},
 volume:{units:['Liter','Milliliter','Cubic meter','US gallon','Cup'],base:[1,.001,1000,3.785411784,.2365882365]},
 area:{units:['Square meter','Square kilometer','Square foot','Acre','Hectare'],base:[1,1000000,.09290304,4046.8564224,10000]},
 data:{units:['Byte','Kilobyte','Megabyte','Gigabyte','Terabyte','Kibibyte','Mebibyte'],base:[1,1000,1e6,1e9,1e12,1024,1048576]},
 speed:{units:['Meters/second','Kilometers/hour','Miles/hour','Knots'],base:[1,1/3.6,.44704,.514444]}
};
function populateUnits(){const set=unitSets[$('unitCategory').value];$('unitFrom').innerHTML=set.units.map((u,i)=>`<option value="${i}">${u}</option>`).join('');$('unitTo').innerHTML=set.units.map((u,i)=>`<option value="${i}" ${i===1?'selected':''}>${u}</option>`).join('');convertUnit();}
function convertUnit(){const cat=$('unitCategory').value;const value=Number($('unitInput').value);if(!Number.isFinite(value)){ $('unitOutput').textContent='—';return;}const from=+$('unitFrom').value,to=+$('unitTo').value;let result;if(cat==='temperature'){const c=from===0?value:from===1?(value-32)*5/9:value-273.15;result=to===0?c:to===1?c*9/5+32:c+273.15;}else{const set=unitSets[cat];result=value*set.base[from]/set.base[to];}$('unitOutput').textContent=Number(result.toPrecision(9)).toLocaleString();$('unitHint').textContent=`${value} ${unitSets[cat].units[from]} = ${Number(result.toPrecision(9))} ${unitSets[cat].units[to]}`;}
$('unitCategory').addEventListener('change',populateUnits);['unitInput','unitFrom','unitTo'].forEach(id=>$(id).addEventListener('input',convertUnit));$('swapUnits').addEventListener('click',()=>{const a=$('unitFrom').value;$('unitFrom').value=$('unitTo').value;$('unitTo').value=a;convertUnit();});populateUnits();
$$('[data-convert-tab]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-convert-tab]').forEach(x=>x.classList.toggle('active',x===btn));$('unitConverter').classList.toggle('hidden',btn.dataset.convertTab!=='unit');$('currencyConverter').classList.toggle('hidden',btn.dataset.convertTab!=='currency');}));
$('swapCurrency').addEventListener('click',()=>{const a=$('currencyFrom').value;$('currencyFrom').value=$('currencyTo').value;$('currencyTo').value=a;});
$('convertCurrency').addEventListener('click',async()=>{const amount=Number($('currencyAmount').value);const from=$('currencyFrom').value,to=$('currencyTo').value;if(!(amount>=0)){toast('Enter a valid amount.');return;}if(from===to){$('currencyResult').textContent=`${amount.toLocaleString()} ${to}`;$('currencyMeta').textContent='Same currency';return;}const btn=$('convertCurrency');btn.disabled=true;btn.textContent='Loading rate…';try{const res=await fetch(`https://open.er-api.com/v6/latest/${encodeURIComponent(from)}`);if(!res.ok)throw Error('Network error');const data=await res.json();if(data.result!=='success'||!data.rates[to])throw Error('Rate unavailable');const rate=data.rates[to];$('currencyResult').textContent=`${(amount*rate).toLocaleString(undefined,{maximumFractionDigits:4})} ${to}`;$('currencyMeta').textContent=`1 ${from} = ${rate} ${to} · ${data.time_last_update_utc||'latest available rate'}`;}catch{$('currencyMeta').textContent='Could not reach the exchange-rate service. Check your connection and try again.';toast('Exchange rate unavailable.');}finally{btn.disabled=false;btn.innerHTML='Get exchange rate <span>↗</span>';}});

// Notes
let notes=store.get('notes',[]);
function renderNotes(){ $('notesCount').textContent=`${notes.length} note${notes.length===1?'':'s'}`;const list=$('notesList');if(!notes.length){list.className='stack-list empty-state';list.textContent='No notes yet. Add your first one.';return;}list.className='stack-list';list.innerHTML=notes.slice().sort((a,b)=>b.updated-a.updated).map(n=>`<article class="note-item"><div><strong>${escapeHTML(n.title||'Untitled note')}</strong><p>${escapeHTML(n.body)}</p><small class="muted">${new Date(n.updated).toLocaleString()}</small></div><div class="item-actions"><button class="mini-btn" data-edit-note="${n.id}">Edit</button><button class="mini-btn" data-delete-note="${n.id}">×</button></div></article>`).join('');}
$('saveNote').addEventListener('click',()=>{const title=$('noteTitle').value.trim(),body=$('noteBody').value.trim();if(!title&&!body){toast('Write something before saving.');return;}const id=$('editingNoteId').value;if(id){notes=notes.map(n=>n.id===id?{...n,title,body,updated:Date.now()}:n);}else notes.push({id:crypto.randomUUID?.()||String(Date.now()),title,body,updated:Date.now()});store.set('notes',notes);$('noteTitle').value='';$('noteBody').value='';$('editingNoteId').value='';$('saveNote').textContent='Save note ＋';renderNotes();toast('Note saved.');});
$('clearNote').addEventListener('click',()=>{$('noteTitle').value='';$('noteBody').value='';$('editingNoteId').value='';});
$('notesList').addEventListener('click',e=>{const edit=e.target.closest('[data-edit-note]'),del=e.target.closest('[data-delete-note]');if(edit){const n=notes.find(x=>x.id===edit.dataset.editNote);if(n){$('noteTitle').value=n.title;$('noteBody').value=n.body;$('editingNoteId').value=n.id;$('saveNote').textContent='Update note ✓';$('noteTitle').focus();}}if(del){notes=notes.filter(x=>x.id!==del.dataset.deleteNote);store.set('notes',notes);renderNotes();toast('Note deleted.');}});renderNotes();

// To-do list
let tasks=store.get('tasks',[]);
function renderTasks(){const done=tasks.filter(t=>t.done).length;$('taskTotal').textContent=tasks.length;$('taskDone').textContent=done;$('taskProgress').textContent=tasks.length?Math.round(done/tasks.length*100)+'%':'0%';$('taskProgressBar').style.width=tasks.length?done/tasks.length*100+'%':'0%';const list=$('taskList');if(!tasks.length){list.className='stack-list empty-state';list.textContent='Nothing on the list. Enjoy the breathing room.';return;}list.className='stack-list';list.innerHTML=tasks.map(t=>`<div class="task-item ${t.done?'done':''}"><input class="task-check" type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''}><div><strong>${escapeHTML(t.text)}</strong><small class="muted">${new Date(t.created).toLocaleDateString()}</small></div><span class="priority ${t.priority}">${t.priority}</span><button class="mini-btn" data-task-delete="${t.id}">×</button></div>`).join('');}
$('taskForm').addEventListener('submit',e=>{e.preventDefault();const text=$('taskInput').value.trim();if(!text)return;tasks.unshift({id:crypto.randomUUID?.()||String(Date.now()),text,priority:$('taskPriority').value,done:false,created:Date.now()});store.set('tasks',tasks);$('taskInput').value='';renderTasks();});
$('taskList').addEventListener('change',e=>{if(e.target.matches('[data-task-check]')){tasks=tasks.map(t=>t.id===e.target.dataset.taskCheck?{...t,done:e.target.checked}:t);store.set('tasks',tasks);renderTasks();}});
$('taskList').addEventListener('click',e=>{const b=e.target.closest('[data-task-delete]');if(b){tasks=tasks.filter(t=>t.id!==b.dataset.taskDelete);store.set('tasks',tasks);renderTasks();}});
$('clearCompleted').addEventListener('click',()=>{tasks=tasks.filter(t=>!t.done);store.set('tasks',tasks);renderTasks();});renderTasks();

// Alarm, timer and stopwatch
let alarmTimeout=null,alarmTarget=null,timerInterval=null,timerRemaining=0,stopwatchInterval=null,stopwatchStart=0,stopwatchElapsed=0,lapCount=0;
function alarmCheck(){if(alarmTarget&&Date.now()>=alarmTarget.at){clearInterval(alarmTimeout);alarmTimeout=null;alert(`Alarm: ${alarmTarget.label||'Time is up!'}`);$('alarmState').textContent='Alarm finished';alarmTarget=null;}}
$('setAlarm').addEventListener('click',()=>{const value=$('alarmTime').value;if(!value){toast('Choose an alarm time.');return;}const [h,m]=value.split(':').map(Number);const now=new Date(),target=new Date();target.setHours(h,m,0,0);if(target<=now)target.setDate(target.getDate()+1);alarmTarget={at:target.getTime(),label:$('alarmLabel').value.trim()};clearInterval(alarmTimeout);alarmTimeout=setInterval(alarmCheck,500);$('alarmState').textContent=`Set for ${target.toLocaleString()}${alarmTarget.label?' · '+alarmTarget.label:''}`;toast('Alarm set while this page stays open.');});
function showTimer(){const mm=Math.floor(timerRemaining/60),ss=timerRemaining%60;$('timerReadout').textContent=`${String(mm).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;}
$('timerStart').addEventListener('click',()=>{if(timerInterval){clearInterval(timerInterval);timerInterval=null;$('timerStart').textContent='Resume';return;}if(timerRemaining<=0)timerRemaining=Math.max(0,Number($('timerMinutes').value||0)*60+Number($('timerSeconds').value||0));if(timerRemaining<=0){toast('Set a timer duration first.');return;}$('timerStart').textContent='Pause';timerInterval=setInterval(()=>{timerRemaining--;showTimer();if(timerRemaining<=0){clearInterval(timerInterval);timerInterval=null;$('timerStart').textContent='Start';alert('Timer complete!');}},1000);});
$('timerReset').addEventListener('click',()=>{clearInterval(timerInterval);timerInterval=null;timerRemaining=Math.max(0,Number($('timerMinutes').value||0)*60+Number($('timerSeconds').value||0));$('timerStart').textContent='Start';showTimer();});['timerMinutes','timerSeconds'].forEach(id=>$(id).addEventListener('input',()=>{if(!timerInterval){timerRemaining=Math.max(0,Number($('timerMinutes').value||0)*60+Number($('timerSeconds').value||0));showTimer();}}));showTimer();
function formatSW(ms){const total=Math.floor(ms/10),cs=total%100,sec=Math.floor(total/100)%60,min=Math.floor(total/6000);return `${String(min).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(cs).padStart(2,'0')}`;}
$('stopwatchStart').addEventListener('click',()=>{if(stopwatchInterval){stopwatchElapsed+=Date.now()-stopwatchStart;clearInterval(stopwatchInterval);stopwatchInterval=null;$('stopwatchStart').textContent='Resume';}else{stopwatchStart=Date.now();stopwatchInterval=setInterval(()=>$('stopwatchReadout').textContent=formatSW(stopwatchElapsed+Date.now()-stopwatchStart),30);$('stopwatchStart').textContent='Pause';}});
$('stopwatchLap').addEventListener('click',()=>{const elapsed=stopwatchElapsed+(stopwatchInterval?Date.now()-stopwatchStart:0);if(!elapsed){toast('Start the stopwatch first.');return;}lapCount++;$('lapList').innerHTML=`<div>Lap ${lapCount} · ${formatSW(elapsed)}</div>`+$('lapList').innerHTML;});
$('stopwatchReset').addEventListener('click',()=>{clearInterval(stopwatchInterval);stopwatchInterval=null;stopwatchElapsed=0;lapCount=0;$('stopwatchReadout').textContent='00:00.00';$('stopwatchStart').textContent='Start';$('lapList').innerHTML='';});

// Calendar and reminders
let calDate=new Date(),selectedDate=dateKey(new Date()),reminders=store.get('reminders',{});
function renderCalendar(){const y=calDate.getFullYear(),m=calDate.getMonth();$('calendarTitle').textContent=calDate.toLocaleDateString(undefined,{month:'long',year:'numeric'});const first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=new Date(y,m,1-offset);let html='';for(let i=0;i<42;i++){const d=new Date(start);d.setDate(start.getDate()+i);const key=dateKey(d),classes=['day-cell'];if(d.getMonth()!==m)classes.push('other');if(key===dateKey(new Date()))classes.push('today');if(key===selectedDate)classes.push('selected');if((reminders[key]||[]).length)classes.push('has-event');html+=`<button class="${classes.join(' ')}" data-day="${key}">${d.getDate()}</button>`;} $('calendarDays').innerHTML=html;renderReminders();}
function renderReminders(){$('selectedDateLabel').textContent=dateLabel(selectedDate);const arr=reminders[selectedDate]||[];const list=$('reminderList');if(!arr.length){list.className='stack-list empty-state';list.textContent='No reminders for this date.';return;}list.className='stack-list';list.innerHTML=arr.map(r=>`<div class="reminder-item"><span>${escapeHTML(r.time||'Any time')} · ${escapeHTML(r.text)}</span><button class="mini-btn" data-reminder-delete="${r.id}">×</button></div>`).join('');}
$('prevMonth').addEventListener('click',()=>{calDate.setMonth(calDate.getMonth()-1);renderCalendar();});$('nextMonth').addEventListener('click',()=>{calDate.setMonth(calDate.getMonth()+1);renderCalendar();});$('calendarDays').addEventListener('click',e=>{const b=e.target.closest('[data-day]');if(b){selectedDate=b.dataset.day;renderCalendar();}});
$('reminderForm').addEventListener('submit',e=>{e.preventDefault();const text=$('reminderText').value.trim();if(!text)return;(reminders[selectedDate]??=[]).push({id:String(Date.now()),text,time:$('reminderTime').value});store.set('reminders',reminders);$('reminderText').value='';$('reminderTime').value='';renderCalendar();toast('Reminder saved.');});
$('reminderList').addEventListener('click',e=>{const b=e.target.closest('[data-reminder-delete]');if(b){reminders[selectedDate]=(reminders[selectedDate]||[]).filter(r=>r.id!==b.dataset.reminderDelete);store.set('reminders',reminders);renderCalendar();}});renderCalendar();

// Camera helpers and device APIs
let flashStream=null,qrStream=null,cameraStream=null,qrScanTimer=null;
$('flashToggle').addEventListener('click',async()=>{const status=$('flashStatus');try{if(flashStream){flashStream.getTracks().forEach(t=>t.stop());flashStream=null;$('flashPreview').classList.remove('on');$('flashToggle').textContent='Turn flashlight on';status.textContent='Flashlight off';return;}flashStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});const track=flashStream.getVideoTracks()[0];if(!track.getCapabilities?.().torch){flashStream.getTracks().forEach(t=>t.stop());flashStream=null;status.textContent='Torch is not supported by this camera/browser.';toast('This device does not expose a flashlight control.');return;}await track.applyConstraints({advanced:[{torch:true}]});$('flashPreview').classList.add('on');$('flashToggle').textContent='Turn flashlight off';status.textContent='Torch is on';}catch(err){status.textContent='Could not access flashlight: '+(err.message||'permission denied');toast('Flashlight access failed.');}});
async function stopQR(){if(qrScanTimer)clearInterval(qrScanTimer);qrScanTimer=null;if(qrStream)qrStream.getTracks().forEach(t=>t.stop());qrStream=null;$('qrVideo').classList.add('hidden');$('qrPlaceholder').classList.remove('hidden');}
$('qrStart').addEventListener('click',async()=>{try{if(!('BarcodeDetector'in window)){toast('Live QR scanning is not supported here. Try uploading a QR image.');return;}const detector=new BarcodeDetector({formats:['qr_code']});qrStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('qrVideo').srcObject=qrStream;$('qrVideo').classList.remove('hidden');$('qrPlaceholder').classList.add('hidden');await $('qrVideo').play();qrScanTimer=setInterval(async()=>{try{const codes=await detector.detect($('qrVideo'));if(codes.length){$('qrResult').innerHTML=`<strong>QR found:</strong> ${escapeHTML(codes[0].rawValue)}`;toast('QR code detected.');stopQR();}}catch{}},500);}catch(err){$('qrResult').textContent='Camera unavailable: '+err.message;}});
$('qrStop').addEventListener('click',stopQR);
$('qrImage').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const img=new Image();img.onload=()=>{const c=document.createElement('canvas');c.width=img.width;c.height=img.height;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);if(window.jsQR){const d=ctx.getImageData(0,0,c.width,c.height);const code=jsQR(d.data,d.width,d.height);$('qrResult').textContent=code?`QR found: ${code.data}`:'No QR code found in that image.';}else $('qrResult').textContent='QR image decoder did not load. Check your connection.';URL.revokeObjectURL(img.src);};img.src=URL.createObjectURL(file);});
$('getLocation').addEventListener('click',()=>{if(!navigator.geolocation){$('locationResult').textContent='Geolocation is not supported.';return;}$('locationResult').textContent='Requesting permission…';navigator.geolocation.getCurrentPosition(p=>$('locationResult').textContent=`Latitude: ${p.coords.latitude.toFixed(5)} · Longitude: ${p.coords.longitude.toFixed(5)} · Accuracy: ±${Math.round(p.coords.accuracy)} m`,err=>$('locationResult').textContent=err.message,{enableHighAccuracy:true,timeout:12000});});

// File manager, PDF reader and scan-to-PDF
let chosenFiles=[];function renderFiles(){const list=$('fileList');$('fileCount').textContent=`${chosenFiles.length} file${chosenFiles.length===1?'':'s'}`;if(!chosenFiles.length){list.className='stack-list empty-state';list.textContent='No files selected yet.';return;}list.className='stack-list';list.innerHTML=chosenFiles.map((f,i)=>`<div class="file-item"><span>${f.type.startsWith('image/')?'▧':f.type.startsWith('video/')?'▶':f.type.startsWith('audio/')?'♫':f.type==='application/pdf'?'▤':'▱'}</span><div><strong>${escapeHTML(f.name)}</strong><small>${fmtBytes(f.size)} · ${escapeHTML(f.type||'Unknown file type')}</small></div><button class="mini-btn" data-file-download="${i}">Download</button><button class="mini-btn" data-file-remove="${i}">×</button></div>`).join('');}
function addFiles(files){for(const f of files){if(!chosenFiles.some(x=>x.name===f.name&&x.size===f.size&&x.lastModified===f.lastModified))chosenFiles.push(f);}renderFiles();}
$('filePicker').addEventListener('change',e=>addFiles(e.target.files));$('fileDrop').addEventListener('dragover',e=>{e.preventDefault();$('fileDrop').style.borderColor='#a997ff';});$('fileDrop').addEventListener('dragleave',()=>$('fileDrop').style.borderColor='');$('fileDrop').addEventListener('drop',e=>{e.preventDefault();$('fileDrop').style.borderColor='';addFiles(e.dataTransfer.files);});
$('fileList').addEventListener('click',e=>{const d=e.target.closest('[data-file-download]'),r=e.target.closest('[data-file-remove]');if(d){const f=chosenFiles[+d.dataset.fileDownload];saveBlob(f,f.name);}if(r){chosenFiles.splice(+r.dataset.fileRemove,1);renderFiles();}});
$$('[data-file-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-file-tab]').forEach(x=>x.classList.toggle('active',x===b));$('fileManagerPanel').classList.toggle('hidden',b.dataset.fileTab!=='manager');$('pdfPanel').classList.toggle('hidden',b.dataset.fileTab!=='pdf');}));
let pdfUrl=null,scanPages=[];$('pdfPicker').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=URL.createObjectURL(f);$('pdfFrame').src=pdfUrl;});$('clearPdf').addEventListener('click',()=>{if(pdfUrl)URL.revokeObjectURL(pdfUrl);pdfUrl=null;$('pdfFrame').removeAttribute('src');});
$('scanCapture').addEventListener('change',e=>{const files=[...e.target.files];files.forEach(f=>{const url=URL.createObjectURL(f);scanPages.push({file:f,url});const img=document.createElement('img');img.src=url;img.alt=f.name;$('scanImages').appendChild(img);});e.target.value='';});
$('makePdf').addEventListener('click',async()=>{if(!scanPages.length){toast('Capture or add at least one scan page.');return;}if(!window.jspdf?.jsPDF){toast('PDF export library did not load. Connect to the internet and reload.');return;}const {jsPDF}=window.jspdf;const doc=new jsPDF({orientation:'p',unit:'mm',format:'a4'});for(let i=0;i<scanPages.length;i++){if(i)doc.addPage();const data=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(scanPages[i].file);});const img=new Image();await new Promise(resolve=>{img.onload=resolve;img.src=data;});const pageW=210,pageH=297,scale=Math.min(pageW/img.width,pageH/img.height);const w=img.width*scale,h=img.height*scale;doc.addImage(data,'JPEG',(pageW-w)/2,(pageH-h)/2,w,h);}doc.save('orbit-scan.pdf');});

// Media studio tabs
const mediaPanels={music:'musicPanel',video:'videoPanel',gallery:'galleryPanel',drawing:'drawingPanel',voice:'voicePanel',camera:'cameraPanel'};
$$('[data-media-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-media-tab]').forEach(x=>x.classList.toggle('active',x===b));Object.entries(mediaPanels).forEach(([k,id])=>$(id).classList.toggle('hidden',k!==b.dataset.mediaTab));}));
// Music
let musicTracks=[],musicCurrent=0;function loadTrack(i){if(!musicTracks.length)return;musicCurrent=(i+musicTracks.length)%musicTracks.length;const p=$('audioPlayer');p.src=musicTracks[musicCurrent].url;p.classList.remove('hidden');p.play().catch(()=>{});renderMusic();}
function renderMusic(){$('musicList').className=musicTracks.length?'stack-list':'stack-list empty-state';$('musicList').innerHTML=musicTracks.length?musicTracks.map((t,i)=>`<div class="track-item"><span>♫</span><div><strong>${escapeHTML(t.name)}</strong><small class="muted">${fmtBytes(t.file.size)}</small></div><button class="mini-btn" data-track-play="${i}">${i===musicCurrent?'Playing':'Play'}</button></div>`).join(''):'No tracks loaded.';}
$('musicFiles').addEventListener('change',e=>{[...e.target.files].forEach(file=>musicTracks.push({name:file.name,file,url:URL.createObjectURL(file)}));renderMusic();if(musicTracks.length===e.target.files.length)loadTrack(0);e.target.value='';});$('musicList').addEventListener('click',e=>{const b=e.target.closest('[data-track-play]');if(b)loadTrack(+b.dataset.trackPlay);});$('audioPlayer').addEventListener('ended',()=>{if(musicTracks.length>1)loadTrack(musicCurrent+1);});
// Video
let videoUrl=null;$('videoFile').addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(videoUrl)URL.revokeObjectURL(videoUrl);videoUrl=URL.createObjectURL(f);$('videoPlayer').src=videoUrl;$('videoPlayer').classList.remove('hidden');});
// Photo gallery + filter + export
let galleryItems=[],selectedGallery=0,currentPhotoFilter='none';function renderGallery(){$('galleryGrid').className=galleryItems.length?'gallery-grid':'gallery-grid empty-state';$('galleryGrid').innerHTML=galleryItems.length?galleryItems.map((g,i)=>`<button class="gallery-thumb ${i===selectedGallery?'selected':''}" data-gallery-index="${i}"><img src="${g.url}" style="filter:${currentPhotoFilter}" alt=""><span>${escapeHTML(g.file.name)}</span></button>`).join(''):'Choose photos to see them here.';}
$('galleryFiles').addEventListener('change',e=>{[...e.target.files].forEach(f=>galleryItems.push({file:f,url:URL.createObjectURL(f)}));selectedGallery=Math.max(0,galleryItems.length-1);renderGallery();e.target.value='';});$('galleryGrid').addEventListener('click',e=>{const b=e.target.closest('[data-gallery-index]');if(b){selectedGallery=+b.dataset.galleryIndex;renderGallery();}});
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));currentPhotoFilter=b.dataset.filter;renderGallery();}));
$('downloadPhoto').addEventListener('click',()=>{const item=galleryItems[selectedGallery];if(!item){toast('Choose a photo first.');return;}const img=new Image();img.onload=()=>{const c=$('editCanvas');c.width=img.naturalWidth;c.height=img.naturalHeight;const ctx=c.getContext('2d');ctx.filter=currentPhotoFilter;ctx.drawImage(img,0,0);c.toBlob(blob=>saveBlob(blob,'orbit-edited-photo.png'));};img.src=item.url;});
// Drawing pad
const drawCanvas=$('drawingCanvas'),drawCtx=drawCanvas.getContext('2d');let drawing=false,lastPoint=null;drawCtx.lineCap='round';drawCtx.lineJoin='round';drawCtx.fillStyle='#f5f3ee';drawCtx.fillRect(0,0,drawCanvas.width,drawCanvas.height);
function canvasPoint(e){const r=drawCanvas.getBoundingClientRect();return{x:(e.clientX-r.left)*drawCanvas.width/r.width,y:(e.clientY-r.top)*drawCanvas.height/r.height};}
drawCanvas.addEventListener('pointerdown',e=>{drawing=true;lastPoint=canvasPoint(e);drawCanvas.setPointerCapture(e.pointerId);});drawCanvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=canvasPoint(e);drawCtx.strokeStyle=$('drawColor').value;drawCtx.lineWidth=+$('drawSize').value;drawCtx.beginPath();drawCtx.moveTo(lastPoint.x,lastPoint.y);drawCtx.lineTo(p.x,p.y);drawCtx.stroke();lastPoint=p;});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>drawCanvas.addEventListener(ev,()=>{drawing=false;lastPoint=null;}));
$('clearCanvas').addEventListener('click',()=>{drawCtx.fillStyle='#f5f3ee';drawCtx.fillRect(0,0,drawCanvas.width,drawCanvas.height);});$('saveCanvas').addEventListener('click',()=>drawCanvas.toBlob(b=>saveBlob(b,'orbit-sketch.png')));
// Voice recorder
let recorder=null,recordChunks=[];$('recordStart').addEventListener('click',async()=>{try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});recorder=new MediaRecorder(stream);recordChunks=[];recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data);};recorder.onstop=()=>{const blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});const url=URL.createObjectURL(blob);$('voicePlayback').src=url;$('voicePlayback').classList.remove('hidden');$('voiceDownload').href=url;$('voiceDownload').classList.remove('hidden');stream.getTracks().forEach(t=>t.stop());$('recordStatus').textContent='Recording saved locally.';};recorder.start();$('recordStart').disabled=true;$('recordStop').disabled=false;$('recordStatus').textContent='Recording…';}catch(err){$('recordStatus').textContent='Microphone unavailable: '+err.message;}});
$('recordStop').addEventListener('click',()=>{if(recorder?.state==='recording'){recorder.stop();$('recordStart').disabled=false;$('recordStop').disabled=true;}});
// Camera
$('cameraStart').addEventListener('click',async()=>{try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});$('cameraVideo').srcObject=cameraStream;await $('cameraVideo').play();}catch(err){toast('Camera unavailable: '+err.message);}});
$('cameraStop').addEventListener('click',()=>{if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null;$('cameraVideo').srcObject=null;});
$('cameraCapture').addEventListener('click',()=>{const v=$('cameraVideo');if(!v.videoWidth){toast('Start the camera first.');return;}const c=$('cameraCanvas');c.width=v.videoWidth;c.height=v.videoHeight;c.getContext('2d').drawImage(v,0,0);c.toBlob(blob=>{const url=URL.createObjectURL(blob);const img=document.createElement('img');img.src=url;img.alt='Camera capture';img.style.cssText='width:120px;height:100px;object-fit:cover;border-radius:9px;border:1px solid #30415e';img.title='Click to download';img.addEventListener('click',()=>saveBlob(blob,'orbit-camera.png'));$('cameraShots').prepend(img);},'image/png');});

// Games: Tic-tac-toe
let ttt=['','','','','','','','',''],tttTurn='X',tttOver=false;const wins=[[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]];
function renderTTT(){$('tttBoard').innerHTML=ttt.map((v,i)=>`<button class="ttt-cell" data-ttt="${i}">${v}</button>`).join('');const win=wins.find(line=>line.every(i=>ttt[i]&&ttt[i]===ttt[line[0]]));$('tttStatus').textContent=win?`${ttt[win[0]]} wins!`:ttt.every(Boolean)?'It is a draw.':`${tttTurn} goes next.`;tttOver=!!win||ttt.every(Boolean);}
$('tttBoard').addEventListener('click',e=>{const b=e.target.closest('[data-ttt]');if(!b||tttOver||ttt[+b.dataset.ttt])return;ttt[+b.dataset.ttt]=tttTurn;tttTurn=tttTurn==='X'?'O':'X';renderTTT();});$('tttReset').addEventListener('click',()=>{ttt=Array(9).fill('');tttTurn='X';renderTTT();});renderTTT();
// Games tab router
const gamePanels={ttt:'tttPanel','2048':'2048Panel',snake:'snakePanel',wordle:'wordlePanel',sudoku:'sudokuPanel',quiz:'quizPanel'};
$$('[data-game-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-game-tab]').forEach(x=>x.classList.toggle('active',x===b));Object.entries(gamePanels).forEach(([k,id])=>$(id).classList.toggle('hidden',k!==b.dataset.gameTab));if(b.dataset.gameTab==='snake')drawSnake();}));
// 2048
let grid2048=[],score2048=0;function add2048(){const empty=[];grid2048.forEach((row,r)=>row.forEach((v,c)=>{if(!v)empty.push([r,c]);}));if(empty.length){const [r,c]=empty[Math.floor(Math.random()*empty.length)];grid2048[r][c]=Math.random()<.9?2:4;}}
function reset2048(){grid2048=Array.from({length:4},()=>Array(4).fill(0));score2048=0;add2048();add2048();render2048();}
function render2048(){$('2048Score').textContent=score2048;$('board2048').innerHTML=grid2048.flat().map(v=>`<div class="tile-2048" data-value="${v||''}">${v||''}</div>`).join('');}
function move2048(dir){const old=JSON.stringify(grid2048);for(let i=0;i<4;i++){let line=dir==='left'||dir==='right'?grid2048[i].slice():grid2048.map(row=>row[i]);if(dir==='right'||dir==='down')line.reverse();let vals=line.filter(Boolean),out=[];for(let j=0;j<vals.length;j++){if(vals[j]===vals[j+1]){out.push(vals[j]*2);score2048+=vals[j]*2;j++;}else out.push(vals[j]);}while(out.length<4)out.push(0);if(dir==='right'||dir==='down')out.reverse();if(dir==='left'||dir==='right')grid2048[i]=out;else out.forEach((v,r)=>grid2048[r][i]=v);}if(old!==JSON.stringify(grid2048)){add2048();render2048();if(grid2048.flat().includes(2048))toast('2048! You made the tile.');}}
$('2048Reset').addEventListener('click',reset2048);document.addEventListener('keydown',e=>{if(!$('2048Panel').classList.contains('hidden')&&$('view-games').classList.contains('active')){const map={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};if(map[e.key]){e.preventDefault();move2048(map[e.key]);}}});let touchStart=null;$('board2048').addEventListener('touchstart',e=>{touchStart=[e.touches[0].clientX,e.touches[0].clientY];},{passive:true});$('board2048').addEventListener('touchend',e=>{if(!touchStart)return;const dx=e.changedTouches[0].clientX-touchStart[0],dy=e.changedTouches[0].clientY-touchStart[1];if(Math.max(Math.abs(dx),Math.abs(dy))>25)move2048(Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up'));touchStart=null;});reset2048();
// Snake
const snakeCanvas=$('snakeCanvas'),snakeCtx=snakeCanvas.getContext('2d');let snake=[],snakeFood={x:8,y:5},snakeDir={x:1,y:0},snakeTimer=null,snakeScore=0;const cell=20;function drawSnake(){snakeCtx.fillStyle='#0b1423';snakeCtx.fillRect(0,0,snakeCanvas.width,snakeCanvas.height);snake.forEach((p,i)=>{snakeCtx.fillStyle=i?'#58b89b':'#a5e9c9';snakeCtx.fillRect(p.x*cell+1,p.y*cell+1,cell-2,cell-2);});snakeCtx.fillStyle='#f18a9d';snakeCtx.beginPath();snakeCtx.arc(snakeFood.x*cell+10,snakeFood.y*cell+10,7,0,Math.PI*2);snakeCtx.fill();}
function startSnake(){clearInterval(snakeTimer);snake=[{x:8,y:8},{x:7,y:8},{x:6,y:8}];snakeDir={x:1,y:0};snakeScore=0;placeFood();$('snakeScore').textContent='Score: 0';drawSnake();snakeTimer=setInterval(()=>{const head={x:snake[0].x+snakeDir.x,y:snake[0].y+snakeDir.y};if(head.x<0||head.y<0||head.x>=24||head.y>=18||snake.some(p=>p.x===head.x&&p.y===head.y)){clearInterval(snakeTimer);snakeTimer=null;toast(`Game over · Score ${snakeScore}`);return;}snake.unshift(head);if(head.x===snakeFood.x&&head.y===snakeFood.y){snakeScore+=10;$('snakeScore').textContent=`Score: ${snakeScore}`;placeFood();}else snake.pop();drawSnake();},115);}
function placeFood(){snakeFood={x:Math.floor(Math.random()*24),y:Math.floor(Math.random()*18)};if(snake.some(p=>p.x===snakeFood.x&&p.y===snakeFood.y))placeFood();}
function changeSnake(d){const dirs={up:{x:0,y:-1},down:{x:0,y:1},left:{x:-1,y:0},right:{x:1,y:0}};const n=dirs[d];if(n&&!(n.x===-snakeDir.x&&n.y===-snakeDir.y))snakeDir=n;}
$('snakeStart').addEventListener('click',startSnake);$$('[data-dir]').forEach(b=>b.addEventListener('click',()=>changeSnake(b.dataset.dir)));document.addEventListener('keydown',e=>{if($('snakePanel').classList.contains('hidden')||!$('view-games').classList.contains('active'))return;const map={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right'};if(map[e.key]){e.preventDefault();changeSnake(map[e.key]);}});drawSnake();
// Word guess
const words=['PLANT','MUSIC','BRAIN','LIGHT','GRAPE','CHAIR','CLOUD','WATER','FLAME','ROBOT','NIGHT','PLANE','SMILE','STONE','DREAM'];let wordTarget='',wordGuesses=[],wordDone=false;
function newWord(){wordTarget=words[Math.floor(Math.random()*words.length)];wordGuesses=[];wordDone=false;$('wordleInput').disabled=false;$('wordleForm').querySelector('button').disabled=false;$('wordleStatus').textContent='Green = right place · Gold = in the word';renderWord();}
function renderWord(){let html='';for(let r=0;r<6;r++){const guess=wordGuesses[r]||'';let marks=[];const remaining=wordTarget.split('');for(let i=0;i<5;i++){if(guess[i]===wordTarget[i]){marks[i]='correct';remaining[i]=null;}}for(let i=0;i<5;i++){if(!marks[i]&&guess[i]&&remaining.includes(guess[i])){marks[i]='present';remaining[remaining.indexOf(guess[i])]=null;}}for(let i=0;i<5;i++)html+=`<div class="wordle-cell ${marks[i]||''}">${guess[i]||''}</div>`;}$('wordleBoard').innerHTML=html;}
$('wordleForm').addEventListener('submit',e=>{e.preventDefault();if(wordDone)return;const guess=$('wordleInput').value.trim().toUpperCase();if(!/^[A-Z]{5}$/.test(guess)){toast('Enter exactly five letters.');return;}wordGuesses.push(guess);$('wordleInput').value='';renderWord();if(guess===wordTarget){$('wordleStatus').textContent='You got it! ✨';wordDone=true;}else if(wordGuesses.length>=6){$('wordleStatus').textContent=`The word was ${wordTarget}. Try a new one!`;wordDone=true;}else $('wordleStatus').textContent=`${6-wordGuesses.length} guesses left.`;if(wordDone){$('wordleInput').disabled=true;$('wordleForm').querySelector('button').disabled=true;}});$('wordleNew').addEventListener('click',newWord);newWord();
// Sudoku (fixed starter puzzle with validation)
const sudokuPuzzle=['530070000','600195000','098000060','800060003','400803001','700020006','060000280','000419005','000080079'];
const sudokuSolution=['534678912','672195348','198342567','859761423','426853791','713924856','961537284','287419635','345286179'];
function renderSudoku(reset=false){const grid=$('sudokuGrid');if(reset){$$('[data-sudoku]').forEach(inp=>{if(!inp.disabled)inp.value='';inp.classList.remove('invalid');});$('sudokuStatus').textContent='Puzzle reset. Keep going!';return;}let html='';sudokuPuzzle.forEach((row,r)=>row.split('').forEach((v,c)=>{const given=v!=='0';html+=`<input class="sudoku-cell" data-sudoku="${r*9+c}" inputmode="numeric" maxlength="1" value="${given?v:''}" ${given?'disabled':''} aria-label="Row ${r+1}, column ${c+1}">`;}));grid.innerHTML=html;}
$('sudokuGrid').addEventListener('input',e=>{const inp=e.target.closest('[data-sudoku]');if(!inp)return;inp.value=inp.value.replace(/[^1-9]/g,'').slice(0,1);inp.classList.remove('invalid');});
$('sudokuReset').addEventListener('click',()=>renderSudoku(true));
$('sudokuCheck').addEventListener('click',()=>{let complete=true,correct=true;$$('[data-sudoku]').forEach(inp=>{const idx=+inp.dataset.sudoku,r=Math.floor(idx/9),c=idx%9,expected=sudokuSolution[r][c],given=sudokuPuzzle[r][c]!=='0';if(!given){if(!inp.value)complete=false;const bad=!!inp.value&&inp.value!==expected;inp.classList.toggle('invalid',bad);if(bad)correct=false;}});$('sudokuStatus').textContent=!complete?'Keep going — some cells are empty.':correct?'Perfect! The solution is correct. ✨':'Some entries are incorrect. Highlighted cells need another look.';});
renderSudoku();

// Quiz
const quiz=[{q:'Which planet is known as the Red Planet?',a:['Venus','Mars','Jupiter','Mercury'],c:1},{q:'What does HTML stand for?',a:['HyperText Markup Language','High Transfer Machine Link','Hyper Tool Multi Language','Home Text Management Language'],c:0},{q:'How many sides does a hexagon have?',a:['Five','Six','Seven','Eight'],c:1},{q:'Which ocean is the largest?',a:['Atlantic','Indian','Arctic','Pacific'],c:3},{q:'What is the chemical symbol for gold?',a:['Ag','Gd','Au','Go'],c:2}];let quizIndex=0,quizPoints=0,quizAnswered=false;
function renderQuiz(){const q=quiz[quizIndex];$('quizScore').textContent=`Score ${quizPoints}/5`;$('quizQuestion').textContent=`${quizIndex+1}. ${q.q}`;$('quizOptions').innerHTML=q.a.map((a,i)=>`<button class="quiz-option" data-quiz-option="${i}">${escapeHTML(a)}</button>`).join('');$('nextQuiz').disabled=true;$('nextQuiz').textContent=quizIndex===4?'Finish round':'Next question →';quizAnswered=false;}
$('quizOptions').addEventListener('click',e=>{const b=e.target.closest('[data-quiz-option]');if(!b||quizAnswered)return;quizAnswered=true;const chosen=+b.dataset.quizOption,correct=quiz[quizIndex].c;if(chosen===correct)quizPoints++;$$('[data-quiz-option]').forEach((x,i)=>{x.disabled=true;if(i===correct)x.classList.add('correct');else if(i===chosen)x.classList.add('wrong');});$('quizScore').textContent=`Score ${quizPoints}/5`;$('nextQuiz').disabled=false;});$('nextQuiz').addEventListener('click',()=>{if(!quizAnswered)return;if(quizIndex===4){toast(`Quiz complete: ${quizPoints}/5`);quizIndex=0;quizPoints=0;}else quizIndex++;renderQuiz();});renderQuiz();

// Habit tracker
let habits=store.get('habits',[]);const todayKey=dateKey(new Date());function renderHabits(){$('habitDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',day:'numeric',month:'short'});const list=$('habitList');if(!habits.length){list.className='habit-list empty-state';list.textContent='Add a habit to get started.';return;}list.className='habit-list';list.innerHTML=habits.map(h=>`<div class="habit-item ${h.days?.includes(todayKey)?'done':''}"><input type="checkbox" data-habit-check="${h.id}" ${h.days?.includes(todayKey)?'checked':''}><div><strong>${escapeHTML(h.name)}</strong><span class="streak">${h.days?.length||0} day${h.days?.length===1?'':'s'} checked off</span></div><button class="mini-btn" data-habit-delete="${h.id}">×</button></div>`).join('');}
$('habitForm').addEventListener('submit',e=>{e.preventDefault();const name=$('habitInput').value.trim();if(!name)return;habits.push({id:String(Date.now()),name,days:[]});store.set('habits',habits);$('habitInput').value='';renderHabits();});$('habitList').addEventListener('change',e=>{const b=e.target.closest('[data-habit-check]');if(!b)return;habits=habits.map(h=>{if(h.id===b.dataset.habitCheck){h.days=h.days||[];h.days=b.checked?[...new Set([...h.days,todayKey])]:h.days.filter(d=>d!==todayKey);}return h;});store.set('habits',habits);renderHabits();});$('habitList').addEventListener('click',e=>{const b=e.target.closest('[data-habit-delete]');if(b){habits=habits.filter(h=>h.id!==b.dataset.habitDelete);store.set('habits',habits);renderHabits();}});renderHabits();

// Expense tracker
let expenses=store.get('expenses',[]),budget=store.get('budget',0);$('expenseDate').value=dateKey(new Date());function renderExpenses(){const ym=dateKey(new Date()).slice(0,7),monthExpenses=expenses.filter(x=>x.date?.startsWith(ym)),spent=monthExpenses.reduce((s,x)=>s+x.amount,0);$('budgetDisplay').textContent='₹'+Number(budget).toLocaleString('en-IN');$('spentDisplay').textContent='₹'+spent.toLocaleString('en-IN',{maximumFractionDigits:2});$('remainingDisplay').textContent='₹'+(budget-spent).toLocaleString('en-IN',{maximumFractionDigits:2});const list=$('expenseList');if(!expenses.length){list.className='stack-list empty-state';list.textContent='No transactions yet.';return;}list.className='stack-list';list.innerHTML=expenses.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(x=>`<div class="expense-item"><span>₹</span><div><strong>${escapeHTML(x.name)}</strong><small>${escapeHTML(x.category)} · ${escapeHTML(x.date)}</small></div><strong class="amount">− ₹${x.amount.toLocaleString('en-IN',{maximumFractionDigits:2})}</strong><button class="mini-btn" data-expense-delete="${x.id}">×</button></div>`).join('');}
$('editBudget').addEventListener('click',()=>{const v=prompt('Set your monthly budget in INR:',budget||'');if(v!==null&&Number(v)>=0){budget=Number(v);store.set('budget',budget);renderExpenses();}});$('expenseForm').addEventListener('submit',e=>{e.preventDefault();const amount=Number($('expenseAmount').value);if(!(amount>0)){toast('Enter an amount greater than zero.');return;}expenses.push({id:String(Date.now()),name:$('expenseName').value.trim(),amount,category:$('expenseCategory').value,date:$('expenseDate').value});store.set('expenses',expenses);$('expenseName').value='';$('expenseAmount').value='';renderExpenses();});$('expenseList').addEventListener('click',e=>{const b=e.target.closest('[data-expense-delete]');if(b){expenses=expenses.filter(x=>x.id!==b.dataset.expenseDelete);store.set('expenses',expenses);renderExpenses();}});$('clearExpenses').addEventListener('click',()=>{if(confirm('Delete all expense entries?')){expenses=[];store.set('expenses',expenses);renderExpenses();}});renderExpenses();

// Weather with Open-Meteo geocoding + forecast
const weatherCodes={0:'Clear sky',1:'Mainly clear',2:'Partly cloudy',3:'Overcast',45:'Fog',48:'Rime fog',51:'Light drizzle',53:'Drizzle',55:'Dense drizzle',61:'Light rain',63:'Rain',65:'Heavy rain',71:'Light snow',73:'Snow',75:'Heavy snow',80:'Rain showers',81:'Showers',82:'Heavy showers',95:'Thunderstorm',96:'Thunderstorm with hail',99:'Heavy thunderstorm'};
async function fetchWeather(lat,lon,place){$('weatherResult').innerHTML='<div class="weather-placeholder">◌<strong>Loading weather…</strong></div>';try{const url=`https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,wind_speed_10m&daily=temperature_2m_max,temperature_2m_min&timezone=auto`;const res=await fetch(url);if(!res.ok)throw Error('Weather service error');const d=await res.json(),c=d.current,day=d.daily;$('weatherResult').innerHTML=`<div class="weather-content"><div class="weather-main"><h3>${escapeHTML(place)}</h3><div class="temp">${Math.round(c.temperature_2m)}°C</div><div class="condition">${weatherCodes[c.weather_code]||'Current conditions'} · Feels like ${Math.round(c.apparent_temperature)}°C</div></div><div class="weather-side"><div class="weather-stat"><small>HUMIDITY</small><strong>${c.relative_humidity_2m}%</strong></div><div class="weather-stat"><small>WIND</small><strong>${c.wind_speed_10m} km/h</strong></div><div class="weather-stat"><small>TODAY'S HIGH</small><strong>${Math.round(day.temperature_2m_max[0])}°C</strong></div><div class="weather-stat"><small>TODAY'S LOW</small><strong>${Math.round(day.temperature_2m_min[0])}°C</strong></div></div></div>`;}catch(err){$('weatherResult').textContent='Could not load weather. Check your connection and try again.';}}
async function searchWeather(city){try{const res=await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=en&format=json`);const d=await res.json();if(!d.results?.length)throw Error('City not found');const p=d.results[0];fetchWeather(p.latitude,p.longitude,[p.name,p.admin1,p.country].filter(Boolean).join(', '));}catch{$('weatherResult').textContent='Location not found or weather service unavailable.';}}
$('weatherForm').addEventListener('submit',e=>{e.preventDefault();if($('weatherCity').value.trim())searchWeather($('weatherCity').value.trim());});$('weatherLocation').addEventListener('click',()=>{if(!navigator.geolocation){toast('Geolocation is unavailable.');return;}navigator.geolocation.getCurrentPosition(p=>fetchWeather(p.coords.latitude,p.coords.longitude,'Your location'),err=>toast(err.message));});searchWeather('Silchar');

// Fitness step counter (motion estimate + manual fallback)
let steps=store.get('steps',{}),motionOn=false,lastMagnitude=0,lastStepAt=0,stepHandler=null;function getSteps(){return steps[todayKey]||0;}function setSteps(n){steps[todayKey]=Math.max(0,Math.round(n));store.set('steps',steps);renderSteps();}
function renderSteps(){const n=getSteps();$('stepCount').textContent=n.toLocaleString();$('stepProgress').style.width=Math.min(100,n/8000*100)+'%';$('distanceEstimate').textContent=(n*.75/1000).toFixed(2)+' km';$('calorieEstimate').textContent=Math.round(n*.04)+' kcal';$('stepGoalText').textContent=`${Math.max(0,8000-n).toLocaleString()} steps to 8,000 goal`;}
$('stepStart').addEventListener('click',async()=>{if(!('DeviceMotionEvent'in window)){toast('Motion tracking is not supported on this device.');return;}try{if(typeof DeviceMotionEvent.requestPermission==='function'){const permission=await DeviceMotionEvent.requestPermission();if(permission!=='granted')throw Error('Motion permission denied');}stepHandler=e=>{const a=e.accelerationIncludingGravity;if(!a)return;const mag=Math.sqrt((a.x||0)**2+(a.y||0)**2+(a.z||0)**2);const now=Date.now();if(mag-lastMagnitude>2.3&&now-lastStepAt>330){setSteps(getSteps()+1);lastStepAt=now;}lastMagnitude=mag;};window.addEventListener('devicemotion',stepHandler);motionOn=true;$('stepStatus').textContent='Motion tracking active. Keep this page open while moving.';}catch(err){$('stepStatus').textContent=err.message;}});
$('stepStop').addEventListener('click',()=>{if(stepHandler)window.removeEventListener('devicemotion',stepHandler);stepHandler=null;motionOn=false;$('stepStatus').textContent='Motion tracking stopped.';});$('stepAdd').addEventListener('click',()=>setSteps(getSteps()+100));$('stepReset').addEventListener('click',()=>{if(confirm('Reset today’s step count?'))setSteps(0);});renderSteps();

// Soundscapes generated with Web Audio API
let audioCtx=null,soundNodes=[],soundPlaying=false,soundTimer=null,selectedSound='rain';function stopSound(){soundNodes.forEach(n=>{try{n.stop?.();n.disconnect?.();}catch{}});soundNodes=[];if(soundTimer)clearTimeout(soundTimer);soundTimer=null;soundPlaying=false;$('soundToggle').textContent='▶ Play sounds';$('breathingOrb').classList.remove('playing');$('soundStatus').textContent='Sound stopped.';}
function makeNoise(){const length=audioCtx.sampleRate*3,buffer=audioCtx.createBuffer(1,length,audioCtx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<length;i++)data[i]=Math.random()*2-1;const src=audioCtx.createBufferSource();src.buffer=buffer;src.loop=true;const filter=audioCtx.createBiquadFilter();filter.type=selectedSound==='rain'?'lowpass':selectedSound==='ocean'?'bandpass':'highpass';filter.frequency.value=selectedSound==='rain'?1000:selectedSound==='ocean'?450:3500;const gain=audioCtx.createGain();gain.gain.value=selectedSound==='ocean'?.18:selectedSound==='rain'?.12:.08;src.connect(filter).connect(gain).connect(audioCtx.destination);src.start();soundNodes.push(src,filter,gain);return gain;}
function playSound(){if(!audioCtx)audioCtx=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();makeNoise();if(selectedSound==='forest'){[440,554,659].forEach((f,i)=>{const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type='sine';osc.frequency.value=f;gain.gain.value=.008;osc.connect(gain).connect(audioCtx.destination);osc.start();soundNodes.push(osc,gain);});}if(selectedSound==='ocean'){const gain=soundNodes.find(n=>n instanceof GainNode);if(gain){const lfo=audioCtx.createOscillator(),depth=audioCtx.createGain();lfo.frequency.value=.12;depth.gain.value=.12;lfo.connect(depth).connect(gain.gain);lfo.start();soundNodes.push(lfo,depth);}}soundNodes.filter(n=>n instanceof GainNode).forEach(n=>{try{n.gain.value*=+$('soundVolume').value/25;}catch{}});soundPlaying=true;$('soundToggle').textContent='Ⅱ Pause sounds';$('breathingOrb').classList.add('playing');$('soundStatus').textContent=`Playing ${selectedSound} ambience.`;const mins=+$('soundDuration').value;if(mins)soundTimer=setTimeout(stopSound,mins*60000);}
$('soundToggle').addEventListener('click',()=>{if(soundPlaying)stopSound();else playSound();});$('soundVolume').addEventListener('input',()=>{if(soundPlaying){stopSound();playSound();}});$$('[data-sound]').forEach(b=>b.addEventListener('click',()=>{$$('[data-sound]').forEach(x=>x.classList.toggle('active',x===b));selectedSound=b.dataset.sound;$('meditationTitle').textContent={rain:'Let it rain.',noise:'Find a steady rhythm.',ocean:'Go with the flow.',forest:'Step into the quiet.'}[selectedSound];$('meditationText').textContent={rain:'Soft rain, a quieter mind.',noise:'A gentle, even sound to help you focus.',ocean:'Slow waves. Slow breaths.',forest:'A calm ambience for winding down.'}[selectedSound];if(soundPlaying){stopSound();playSound();}}));
window.addEventListener('beforeunload',()=>{if(flashStream)flashStream.getTracks().forEach(t=>t.stop());if(qrStream)qrStream.getTracks().forEach(t=>t.stop());if(cameraStream)cameraStream.getTracks().forEach(t=>t.stop());if(soundPlaying)stopSound();});